<?php
namespace App\Foundation\Console;use App\Foundation\Generation\FilePlan;
final class DocsIndexCommand extends FoundationCommand{protected $signature='docs:index {--dry-run} {--force}';protected $description='Generate docs/INDEX.md from Markdown files.';public function handle(FilePlan $p):int{$files=[];$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator(base_path('docs'),\FilesystemIterator::SKIP_DOTS));foreach($it as $f){if($f->isFile()&&$f->getExtension()==='md'&&!str_contains($f->getPathname(),'/generated/')&&$f->getFilename()!=='INDEX.md')$files[]=$f->getPathname();}sort($files);$md="# Documentation Index\n\n";foreach($files as $f){$rel=str_replace(base_path('docs').'/','',$f);$first=trim(strtok((string)file_get_contents($f),"\n"));$title=str_starts_with($first,'# ')?substr($first,2):$rel;$md.="- [{$title}]({$rel})\n";}$p->write('docs/INDEX.md',$md,true);return $this->runPlan($p,'docs:index');}}
